// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract LogFileHelper {
    struct Message { address Sender; string Data; uint Val; uint Time; }
    Message[] public History;
    Message LastMsg;
    function AddMessage(address _adr, uint _val, string memory _data) public {
        LastMsg.Sender = _adr;
        LastMsg.Time = block.timestamp;
        LastMsg.Val = _val;
        LastMsg.Data = _data;
        History.push(LastMsg);
    }
}

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    LogFileHelper logFile;

    function setUp() public {
        c = new PENNY_BY_PENNY();
        logFile = new LogFileHelper();
        c.SetLogFile(address(logFile));
    }

    function testFuzz_property(uint256 value, uint256 lockTime, address actor) public {
        vm.assume(actor != address(0) && actor != address(c) && actor != address(logFile) && actor != address(this));
        value = bound(value, 0, 1e30);
        lockTime = bound(lockTime, 0, type(uint256).max - block.timestamp);

        vm.deal(actor, value);
        vm.prank(actor);
        bool ok;
        try c.Put{value: value}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
